class Solution {
  public int passwordStrength(String password) {
    boolean[] seen = new boolean[128];
    int strength = 0;
    for (int i = 0; i < password.length(); i++) {
      char c = password.charAt(i);
      if (seen[c]) continue;
      seen[c] = true;
      if (c >= 'a' && c <= 'z') strength += 1;
      else if (c >= 'A' && c <= 'Z') strength += 2;
      else if (c >= '0' && c <= '9') strength += 3;
      else strength += 5;
    }
    return strength;
  }
}
